mapper.update:
UPDATE MEMBER_ACCOUNT
SET STATUS = #{afterStatus},
    UPDATED_AT = NOW()
WHERE CODE = #{memberCode}
  AND STATUS = #{beforeStatus}
  AND DELETE_YN = 0

mapper.sql:
WHERE l.TARGET_TYPE = 'member'
  AND l.TARGET_CODE = #{memberCode}
  AND l.PROCESS_TYPE IN ('RESTRICT', 'RELEASE')

WHERE (
    (
        r.TARGET_TYPE = 'feed'
        AND EXISTS (
            SELECT 1
            FROM FEED f
            WHERE f.CODE = r.TARGET_CODE
              AND f.MEM_CODE = #{memberCode}
        )
    )
    OR
    (
        r.TARGET_TYPE = 'comment'
        AND EXISTS (
            SELECT 1
            FROM COMMENTS c
            WHERE c.CODE = r.TARGET_CODE
              AND c.MEM_CODE = #{memberCode}
        )
    )
    OR
    (
        r.TARGET_TYPE = 'market'
        AND EXISTS (
            SELECT 1
            FROM MARKET_PRODUCT p
            WHERE p.CODE = r.TARGET_CODE
              AND p.MEM_CODE = #{memberCode}
        )
    )
)

mapper.select:
SELECT r.CODE, r.MEM_CODE, r.TARGET_TYPE, r.TARGET_CODE, r.REASON_TYPE, r.CONTENT, r.STATUS, r.CREATED_AT
FROM REPORT r
ORDER BY r.CREATED_AT DESC, r.CODE DESC LIMIT #{perPage} OFFSET #{offset}

SELECT d.CODE AS trade_code, d.PROD_CODE AS product_code, d.PRICE AS trade_price, d.CREATED_AT AS traded_at,
CASE WHEN d.BUYER_ID = m.ID AND d.SELLER_ID = m.ID THEN 'BOTH' WHEN d.BUYER_ID = m.ID THEN 'BUY' ELSE 'SELL' END AS trade_type
FROM MARKET_DEAL_LOG d
JOIN MEMBER_ACCOUNT m ON m.CODE = #{memberCode}
ORDER BY d.CREATED_AT DESC, d.CODE DESC LIMIT #{perPage} OFFSET #{offset}
